-- =============================================================================
-- Seed ModuleInfoItem : import des fiches FAQ patient (chantier 2026-08-06)
-- =============================================================================
--
-- Import initial des Q/R FAQ patient pour 3 centres :
--   - userProductId=2  -> Radiologie Muzillac (MZC.json)
--   - userProductId=12 -> Cognac / SELAS TESLA (A04.json)
--   - userProductId=15 -> CH Menton La Palmosa (MEN.json)
--
-- Idempotent : chaque INSERT est protege par ON CONFLICT (id) DO NOTHING.
-- Rejouer le script ne cree pas de doublons. En revanche, il ne MET PAS A JOUR
-- les items existants -- pour ecraser un item, DELETE + rerun.
--
-- Bump 'moduleInfoVersion' en fin de script pour declencher le refresh Azure
-- au prochain poll (webhook non declenche depuis SQL, mais Azure re-fetchera).
-- =============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- Centre userProductId=2 (MZC.json)
-- ---------------------------------------------------------------------------
-- 49 items generes pour userProductId=2

-- ---------------------------------------------------------------------------
-- Centre userProductId=12 (A04.json)
-- ---------------------------------------------------------------------------
-- 53 items generes pour userProductId=12

-- ---------------------------------------------------------------------------
-- Centre userProductId=15 (MEN.json)
-- ---------------------------------------------------------------------------
-- 43 items generes pour userProductId=15

-- Bump moduleInfoVersion pour les 3 centres
UPDATE "UserProduct" SET "moduleInfoVersion" = NOW() WHERE "id" = 2;
UPDATE "UserProduct" SET "moduleInfoVersion" = NOW() WHERE "id" = 12;
UPDATE "UserProduct" SET "moduleInfoVersion" = NOW() WHERE "id" = 15;

COMMIT;

-- TOTAL : 145 items inseres (hors items skippes pour reponse vide)
