INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('est-il-possible-de-choisir-son-radiologue-pour-un-examen', 2, 'Est-il possible de choisir son radiologue pour un examen ?', 'Non.', NULL, true, 26, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-examens-que-vous-pratiquez-dans-votre-centre', 2, 'Quels sont les examens que vous pratiquez dans votre centre ?', 'Radiographie du crâne, des sinus, du cavum et des os propres du nez ; Panoramique dentaire et articulation temporo-mandibulaire (ATM) ; Radiographie thoracique et du gril costal ; Radiographie de l''abdomen sans préparation (ASP) ; Radiographie du bassin et des hanches ; Radiographies du rachis (cervical, dorsal, lombaire, complet, sacrum-coccyx) ; Radiographies des membres supérieurs (épaule, bras, coude, avant-bras, poignet, main, âge osseux) ; Radiographies des membres inférieurs (hanche, cuisse, genou, jambe, cheville, pied) ; Radiographie du squelette ; Échographie cervicale, thyroïdienne et des glandes salivaires ; Échographie mammaire et des parties molles ; Échographie abdominale et abdomino-pelvienne ; Échographie rénale et vésicale ; Échographie hépatique ; Échographie pelvienne, prostatique et testiculaire ; Échographie musculo-squelettique (épaule, coude, poignet, main, hanche, genou, cheville, pied) ; Échographie de la hanche du nourrisson (dépistage) ; Échographie musculaire et des tendons.', NULL, true, 27, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-assure-t-il-la-realisation-d-examens-en-urgence', 2, 'Votre centre assure-t-il la réalisation d''examens en urgence ?', 'Oui, sur demande par téléphone.', NULL, true, 28, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
