INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-difficultes-particulieres-pour-acceder-a-v-2', 12, 'Existe-t-il des difficultés particulières pour accéder à votre centre ?', 'Le cabinet est situé tout au bout du parking, sur la droite, facilement identifiable par de grandes baies vitrées et une inscription bleue ''Centre d''imagerie médicale''.', NULL, true, 7, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('y-a-t-il-des-places-de-parking-reservees-aux-personnes-han-2', 12, 'Y a-t-il des places de parking réservées aux personnes handicapées (PMR) ?', 'Oui.', NULL, true, 8, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('disposez-vous-d-un-parking-pour-les-patients-2', 12, 'Disposez-vous d''un parking pour les patients ?', 'Oui.', NULL, true, 9, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-transports-en-commun-desservent-votre-centre-2', 12, 'Quels transports en commun desservent votre centre ?', 'Le centre est desservi par la ligne B ou par le bus, arrêt « Pôle Santé ».', NULL, true, 10, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelles-sont-les-heures-d-ouverture-de-votre-centre-2', 12, 'Quelles sont les heures d''ouverture de votre centre ?', 'Centre d''imagerie : du lundi au vendredi de 8h00 à 12h30 et de 14h00 à 18h00. Pôle IRM/Scanner : du lundi au vendredi de 8h00 à 18h00, et le samedi de 8h00 à 12h00.', NULL, true, 11, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelles-sont-les-heures-de-pause-ou-de-fermeture-pendant-l-2', 12, 'Quelles sont les heures de pause ou de fermeture pendant la journée ?', 'Le centre d''imagerie est fermé de 12h30 à 14h00. Le pôle IRM/Scanner fonctionne en journée continue.', NULL, true, 12, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-horaires-de-disponibilite-telephonique-de-v-2', 12, 'Quels sont les horaires de disponibilité téléphonique de vos secrétaires ?', 'Du lundi au vendredi de 8h00 à 12h30 et de 14h00 à 17h30.', NULL, true, 13, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-jours-ou-periodes-de-fermeture-reguliere-2', 12, 'Quels sont les jours ou périodes de fermeture régulière ?', 'Centre d''imagerie : fermé le samedi, le dimanche et les jours fériés. Pôle IRM/Scanner : fermé le samedi après 12h00, le dimanche et les jours fériés. Seuls les examens d''IRM sont réalisables le samedi.', NULL, true, 14, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quel-est-le-numero-de-telephone-de-votre-secretariat-de-ra-2', 12, 'Quel est le numéro de téléphone de votre secrétariat de radiologie ?', 'Ligne patients : 05 45 82 08 80. Ligne professionnels : 05 45 82 08 35.', NULL, true, 15, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
