INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-les-demandes-d-i-2', 12, 'Quelle est l''adresse email du centre pour les demandes d''information générale ?', 'secretaire@radiologie-cognac.com', NULL, true, 17, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-les-demandes-de-2', 12, 'Quelle est l''adresse email du centre pour les demandes de RDV d''examen ?', 'secretaire@radiologie-cognac.com', NULL, true, 18, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-l-envoi-par-le-p-2', 12, 'Quelle est l''adresse email du centre pour l''envoi par le patient d''ordonnances d''examen ?', 'secretaire@radiologie-cognac.com', NULL, true, 19, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
