INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-un-rappel-ou-une-confirmation-de-rendez-vous-2', 12, 'Proposez-vous un rappel ou une confirmation de rendez-vous par SMS ou email ?', 'Oui, par SMS et par email.', NULL, true, 21, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('souhaitez-vous-accepter-les-nouveaux-patients-dans-lyraeta-2', 12, 'Souhaitez-vous accepter les nouveaux patients dans LyraeTalk ?', 'Oui.', NULL, true, 22, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-une-liste-d-attente-ou-un-systeme-de-rappel-2', 12, 'Proposez-vous une liste d''attente ou un système de rappel pour remplacer les rendez-vous annulés ?', 'Oui, une liste d''attente est proposée et renseignée au moment de la prise de rendez-vous.', NULL, true, 23, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-frais-en-cas-d-annulation-tardive-ou-d-abs-2', 12, 'Existe-t-il des frais en cas d''annulation tardive ou d''absence au rendez-vous ?', 'Non.', NULL, true, 24, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('en-cas-d-indisponibilite-de-creneau-dans-votre-centre-vers-2', 12, 'En cas d''indisponibilité de créneau dans votre centre, vers quels autres centres proposez-vous d''orienter le patient ?', 'Nous orientons vers le centre de radiologie du centre hospitalier de Cognac.', NULL, true, 25, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('est-il-possible-de-choisir-son-radiologue-pour-un-examen-2', 12, 'Est-il possible de choisir son radiologue pour un examen ?', 'Non.', NULL, true, 26, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-examens-que-vous-pratiquez-dans-votre-centr-2', 12, 'Quels sont les examens que vous pratiquez dans votre centre ?', 'Radiographie, échographie, doppler artériel, mammographie, ostéodensitométrie, panoramique dentaire, scanner, IRM.', NULL, true, 27, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('combien-de-temps-en-moyenne-le-patient-va-t-il-passer-sur-pl', 12, 'Combien de temps en moyenne le patient va-t-il passer sur place pour chaque examen ?', 'Radiographie : 30 min ; échographie : 45 min ; radio + écho : 1 h ; mammographie : 30 min ; ostéodensitométrie : 45 min ; panoramique dentaire : 30 min ; scanner : 30 min ; IRM : 45 min ; examens interventionnels : 1 h.', NULL, true, 28, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-assure-t-il-la-realisation-d-examens-en-urgen-2', 12, 'Votre centre assure-t-il la réalisation d''examens en urgence ?', 'Oui, pour la radiographie, l''échographie, la mammographie et le scanner.', NULL, true, 29, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('en-cas-d-examen-demande-en-urgence-est-il-possible-de-se-p-2', 12, 'En cas d''examen demandé en urgence, est-il possible de se présenter sans rendez-vous ?', 'Non. Les urgences sont organisées sur demande d''un médecin traitant ou d''un chirurgien de la polyclinique, qui obtient un rendez-vous sur place.', NULL, true, 30, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-des-examens-interventionnels-2', 12, 'Proposez-vous des examens interventionnels ?', 'Oui : infiltrations sous radiographie, échographie ou scanner (lombaire uniquement), biopsie mammaire, ponctions thyroïdiennes, mammaires, kystiques ou d''hématomes, PRP et viscosupplémentations.', NULL, true, 31, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('disposez-vous-d-un-irm-ouvert-ou-semi-ouvert-pour-les-pati-2', 12, 'Disposez-vous d''un IRM ouvert ou semi-ouvert pour les patients claustrophobes ?', 'Non, mais l''IRM dispose d''une ouverture large de 70 cm.', NULL, true, 32, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('avez-vous-des-fiches-de-consignes-pratiques-pour-la-prepar-2', 12, 'Avez-vous des fiches de consignes pratiques pour la préparation aux examens ?', 'Oui, disponibles en annexe.', NULL, true, 33, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('combien-de-radiologues-exercent-dans-ce-centre-2', 12, 'Combien de radiologues exercent dans ce centre ?', 'Un seul radiologue exerce dans ce centre.', NULL, true, 34, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-radiologues-qui-exercent-dans-votre-centre', 12, 'Quels sont les radiologues qui exercent dans votre centre ?', 'Dr Morales Pierrick.', NULL, true, 35, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('les-radiologues-sont-ils-surspecialises-par-domaine-d-imag-2', 12, 'Les radiologues sont-ils surspécialisés par domaine d''imagerie ?', 'Non.', NULL, true, 36, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('le-centre-dispose-t-il-d-un-service-d-imagerie-de-garde-2', 12, 'Le centre dispose-t-il d''un service d''imagerie de garde ?', 'Non.', NULL, true, 37, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-documents-doit-on-apporter-pour-un-examen-2', 12, 'Quels documents doit-on apporter pour un examen ?', 'Ordonnance, carte Vitale ou attestation, mutuelle, pièce d''identité, documents liés à un accident du travail si nécessaire. Pour scanner, IRM et mammographie : apporter les examens antérieurs.', NULL, true, 38, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('combien-de-temps-faut-il-attendre-pour-recevoir-les-result-2', 12, 'Combien de temps faut-il attendre pour recevoir les résultats ?', 'Entre 24 et 48 heures.', NULL, true, 39, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-la-gravure-de-cd-2', 12, 'Proposez-vous la gravure de CD ?', 'Oui.', NULL, true, 40, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-l-impression-des-cliches-sur-film-2', 12, 'Proposez-vous l''impression des clichés sur film ?', 'Oui.', NULL, true, 41, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('comment-acceder-aux-resultats-d-imagerie-sur-internet-2', 12, 'Comment accéder aux résultats d''imagerie sur internet ?', 'Via la plateforme de Web Diffusion.', NULL, true, 42, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('le-compte-rendu-de-l-examen-est-il-automatiquement-envoye-2', 12, 'Le compte-rendu de l''examen est-il automatiquement envoyé à mon médecin traitant ?', 'Oui, si son adresse MS Santé a été renseignée.', NULL, true, 43, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('comment-puis-je-recuperer-une-copie-de-mes-anciens-examens-2', 12, 'Comment puis-je récupérer une copie de mes anciens examens ?', 'Sur demande par email à secretaire@radiologie-cognac.com. Les examens seront mis à disposition via la Web Diffusion.', NULL, true, 44, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('est-il-possible-que-les-images-soient-envoyees-directement-a', 12, 'Est-il possible que les images soient envoyées directement à un autre spécialiste si besoin ?', 'Oui, sur demande écrite.', NULL, true, 45, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-propose-t-il-du-wi-fi-pour-les-patients-2', 12, 'Votre centre propose-t-il du Wi-Fi pour les patients ?', 'Non.', NULL, true, 46, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('disposez-vous-d-une-salle-d-attente-adaptee-aux-enfants-2', 12, 'Disposez-vous d''une salle d''attente adaptée aux enfants ?', 'Non.', NULL, true, 47, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-vos-modes-de-paiement-acceptes-2', 12, 'Quels sont vos modes de paiement acceptés ?', 'Espèces, carte bancaire et chèque.', NULL, true, 48, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('pratiquez-vous-le-tiers-payant-2', 12, 'Pratiquez-vous le tiers payant ?', 'Oui.', NULL, true, 49, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-depassements-d-honoraires-dans-votre-centr-2', 12, 'Existe-t-il des dépassements d''honoraires dans votre centre ?', 'Oui, pour les examens suivants : les infiltrations sous radio ou échographie, les infiltrations sous scanner, les viscosupplémentations, les PRP.', NULL, true, 50, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-montants-des-depassements-d-honoraires-applic', 12, 'Quels sont les montants des dépassements d''honoraires applicables ?', 'Les montants des dépassements d''honoraires applicables sont : 15 € pour les infiltrations sous radio ou échographie, 50 € pour les infiltrations sous scanner, 70 € pour les viscosupplémentations, 150 € pour les PRP.', NULL, true, 51, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-moyens-pour-deposer-une-reclamation-2', 12, 'Quels sont les moyens pour déposer une réclamation ?', 'Par email à secretaire@radiologie-cognac.com ou par courrier à : SELAS TESLA, 71 avenue d''Angoulême, 16100 Châteaubernard.', NULL, true, 52, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quel-est-le-nom-complet-de-votre-centre-3', 15, 'Quel est le nom complet de votre centre ?', 'Le centre s''appelle Centre Hospitalier La Palmosa, situé à Menton.', NULL, true, 0, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-complete-de-votre-centre-3', 15, 'Quelle est l''adresse complète de votre centre ?', 'Le centre est situé au 2 rue Antoine Péglion, 06500 Menton. Il s''agit du Centre Hospitalier de Menton.', NULL, true, 1, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-possede-t-il-un-site-web-et-si-oui-quel-est-s-3', 15, 'Votre centre possède-t-il un site web et, si oui, quel est son lien ?', 'Oui, le centre dispose d''un site web officiel accessible à l''adresse suivante : https://ch-menton.fr/.', NULL, true, 2, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelles-sont-les-modalites-d-acces-a-votre-centre-entree-p-3', 15, 'Quelles sont les modalités d''accès à votre centre (entrée principale, étage, interphone…) ?', 'L''accès au service est fléché et structuré dès le hall d''accueil de l''hôpital. À votre arrivée, veuillez vous enregistrer via la borne d''accueil en prenant un ticket.', NULL, true, 3, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-phrase-dites-vous-au-telephone-au-patient-pour-lui-5', 15, 'Quelle phrase dites-vous au téléphone au patient pour lui expliquer comment trouver l''entrée de votre centre ?', 'À votre arrivée dans le hall principal de l''hôpital, suivez la signalétique jusqu''au service. Merci de vous enregistrer à la borne d''accueil en prenant un ticket.', NULL, true, 4, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-difficultes-particulieres-pour-acceder-a-v-3', 15, 'Existe-t-il des difficultés particulières pour accéder à votre centre ?', 'Non, il n''existe aucune difficulté particulière signalée pour accéder au centre.', NULL, true, 5, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('y-a-t-il-des-places-de-parking-reservees-aux-personnes-han-3', 15, 'Y a-t-il des places de parking réservées aux personnes handicapées (PMR) ?', 'Oui, des places de stationnement réservées aux personnes à mobilité réduite (PMR) sont disponibles directement devant l''entrée principale du centre, facilitant ainsi l''accès aux patients en situation de handicap.', NULL, true, 6, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('disposez-vous-d-un-parking-pour-les-patients-3', 15, 'Disposez-vous d''un parking pour les patients ?', 'Pas de parking à l''hôpital, prévoir de se garer dans les rues proches payantes.', NULL, true, 7, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-transports-en-commun-desservent-votre-centre-3', 15, 'Quels transports en commun desservent votre centre ?', 'L''hôpital est desservi par trois arrêts de bus à proximité : Pagnol Hôpital La Palmosa, Hôpital, et Maison Russe.', NULL, true, 8, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-examens-realisables-le-samedi', 15, 'Quels sont les examens réalisables le samedi ?', 'Des rendez-vous sont possibles le samedi matin uniquement pour les IRM du genou et les IRM lombaires. La prise de rendez-vous se fait exclusivement via le secrétariat (pas de réservation en ligne ni via le robot).', NULL, true, 9, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelles-sont-les-heures-d-ouverture-de-votre-centre-3', 15, 'Quelles sont les heures d''ouverture de votre centre ?', 'L''hôpital est ouvert 24 heures sur 24, 7 jours sur 7, sans aucune pause ni fermeture en cours de journée, et sans jours de fermeture régulière. Il assure une continuité de service permanente tout au long de l''année.', NULL, true, 10, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelles-sont-les-heures-de-pause-ou-de-fermeture-pendant-l-3', 15, 'Quelles sont les heures de pause ou de fermeture pendant la journée ?', 'Il n''existe aucune heure de pause ni de fermeture pendant la journée. L''hôpital est ouvert en continu 24h/24.', NULL, true, 11, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-horaires-de-disponibilite-telephonique-de-v-3', 15, 'Quels sont les horaires de disponibilité téléphonique de vos secrétaires ?', 'Les secrétaires du service imagerie de l''hôpital sont joignables par téléphone du lundi au vendredi, de 08h00 à 18h00.', NULL, true, 12, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-jours-ou-periodes-de-fermeture-reguliere-3', 15, 'Quels sont les jours ou périodes de fermeture régulière ?', 'Il n''existe aucun jour ni aucune période de fermeture régulière. Le centre est ouvert toute l''année, y compris les jours fériés.', NULL, true, 13, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quel-est-le-numero-de-telephone-de-votre-secretariat-de-ra-3', 15, 'Quel est le numéro de téléphone de votre secrétariat de radiologie ?', 'Le numéro de téléphone du secrétariat de radiologie est le 04 93 28 72 32.', NULL, true, 14, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quel-est-le-numero-de-telephone-et-l-adresse-email-pour-co-3', 15, 'Quel est le numéro de téléphone et l''adresse email pour contacter un(e) responsable du service ?', 'secretariat.radiologie@ch-menton.fr', NULL, true, 15, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-les-demandes-d-i-3', 15, 'Quelle est l''adresse email du centre pour les demandes d''information générale ?', 'secretariat.radiologie@ch-menton.fr', NULL, true, 16, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-les-demandes-de-3', 15, 'Quelle est l''adresse email du centre pour les demandes de RDV d''examen ?', 'secretariat.radiologie@ch-menton.fr', NULL, true, 17, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quelle-est-l-adresse-email-du-centre-pour-l-envoi-par-le-p-3', 15, 'Quelle est l''adresse email du centre pour l''envoi par le patient d''ordonnances d''examen ?', 'secretariat.radiologie@ch-menton.fr', NULL, true, 18, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-la-prise-de-rendez-vous-en-ligne-3', 15, 'Proposez-vous la prise de rendez-vous en ligne ?', 'Oui, la prise de rendez-vous en ligne est disponible directement sur le site officiel du centre : ch-menton.fr ou bien sur Doctolib.', NULL, true, 19, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-un-rappel-ou-une-confirmation-de-rendez-vous-3', 15, 'Proposez-vous un rappel ou une confirmation de rendez-vous par SMS ou email ?', 'Un SMS est envoyé 3 jours avant le rendez-vous avec un rappel, les consignes à suivre et les documents nécessaires.', NULL, true, 20, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('souhaitez-vous-accepter-les-nouveaux-patients-dans-lyraeta-3', 15, 'Souhaitez-vous accepter les nouveaux patients dans LyraeTalk ?', 'Oui.', NULL, true, 21, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('proposez-vous-une-liste-d-attente-ou-un-systeme-de-rappel-3', 15, 'Proposez-vous une liste d''attente ou un système de rappel pour remplacer les rendez-vous annulés ?', 'Non.', NULL, true, 22, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-frais-en-cas-d-annulation-tardive-ou-d-abs-3', 15, 'Existe-t-il des frais en cas d''annulation tardive ou d''absence au rendez-vous ?', 'Non, pas de frais en cas d''annulation tardive ou d''absence au rendez-vous.', NULL, true, 23, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-examens-que-vous-pratiquez-dans-votre-centr-3', 15, 'Quels sont les examens que vous pratiquez dans votre centre ?', 'Radiographie, échographie, doppler / écho-doppler, mammographie, scanner et IRM.', NULL, true, 24, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('combien-de-temps-en-moyenne-le-patient-va-t-il-passer-sur-2', 15, 'Combien de temps en moyenne le patient va-t-il passer sur place pour chaque examen ?', 'Entre 30 et 60 minutes.', NULL, true, 25, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-assure-t-il-la-realisation-d-examens-en-urgen-3', 15, 'Votre centre assure-t-il la réalisation d''examens en urgence ?', 'Oui, les examens en urgence sont pris en charge uniquement via le service des urgences.', NULL, true, 26, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('en-cas-d-examen-demande-en-urgence-est-il-possible-de-se-p-3', 15, 'En cas d''examen demandé en urgence, est-il possible de se présenter sans rendez-vous ?', 'Non, les consultations sans rendez-vous ne sont pas possibles, sauf en passant par le service des urgences.', NULL, true, 27, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('en-cas-d-urgence-medicale-quelle-consigne-donnez-vous-lors-d', 15, 'En cas d''urgence médicale, quelle consigne donnez-vous lors de la fermeture du secrétariat ?', 'En cas d''urgence vitale pendant la fermeture du secrétariat, il est demandé d''appeler le 15.', NULL, true, 28, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('les-radiologues-sont-ils-surspecialises-par-domaine-d-imag-3', 15, 'Les radiologues sont-ils surspécialisés par domaine d''imagerie ?', 'Oui, les radiologues interviennent par domaines de spécialisation, notamment en urologie (prostate), en neurologie et en gynécologie/pelvis.', NULL, true, 29, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('le-centre-dispose-t-il-d-un-service-d-imagerie-de-garde-3', 15, 'Le centre dispose-t-il d''un service d''imagerie de garde ?', 'Oui, le centre dispose du service de garde qui est réservé uniquement au service des urgences.', NULL, true, 30, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-documents-doit-on-apporter-pour-un-examen-3', 15, 'Quels documents doit-on apporter pour un examen ?', 'Carte vitale, mutuelle, attestation d''assurance maladie si la carte vitale est absente, ordonnance, anciens examens concernant le problème en cours, et mode de paiement (chèque, carte bleue, espèces).', NULL, true, 31, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('comment-acceder-aux-resultats-d-imagerie-sur-internet-3', 15, 'Comment accéder aux résultats d''imagerie sur internet ?', 'Un code d''accès est remis le jour de l''examen par la secrétaire, permettant de consulter les résultats en ligne.', NULL, true, 32, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('le-compte-rendu-de-l-examen-est-il-automatiquement-envoye-3', 15, 'Le compte-rendu de l''examen est-il automatiquement envoyé à mon médecin traitant ?', 'Oui, le compte rendu est envoyé au médecin prescripteur (traitant).', NULL, true, 33, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('comment-puis-je-recuperer-une-copie-de-mes-anciens-examens-3', 15, 'Comment puis-je récupérer une copie de mes anciens examens ?', 'La demande peut être effectuée par e-mail ou directement sur place. Une facturation peut s''appliquer.', NULL, true, 34, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('est-il-possible-que-les-images-soient-envoyees-directement-2', 15, 'Est-il possible que les images soient envoyées directement à un autre spécialiste si besoin ?', 'Oui, la transmission des résultats d''examen est possible, mais uniquement vers les hôpitaux publics des Alpes-Maritimes.', NULL, true, 35, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('votre-centre-propose-t-il-du-wi-fi-pour-les-patients-3', 15, 'Votre centre propose-t-il du Wi-Fi pour les patients ?', 'Oui.', NULL, true, 36, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('disposez-vous-d-une-salle-d-attente-adaptee-aux-enfants-3', 15, 'Disposez-vous d''une salle d''attente adaptée aux enfants ?', 'Non.', NULL, true, 37, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-vos-modes-de-paiement-acceptes-3', 15, 'Quels sont vos modes de paiement acceptés ?', 'Espèces, carte bancaire et chèque.', NULL, true, 38, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('pratiquez-vous-le-tiers-payant-3', 15, 'Pratiquez-vous le tiers payant ?', 'Le tiers payant est pratiqué, mais uniquement avec les complémentaires santé ayant signé un accord préalable avec le centre. Il est conseillé de se renseigner directement à l''accueil avant votre venue pour vérifier si votre mutuelle est concernée.', NULL, true, 39, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('existe-t-il-des-depassements-d-honoraires-dans-votre-centr-3', 15, 'Existe-t-il des dépassements d''honoraires dans votre centre ?', 'Oui, des dépassements d''honoraires s''appliquent sur certains actes spécifiques : les infiltrations et ponctions sous échographie et sous radiographie, les biopsies, ainsi que les échographies et mammographies réalisées par les radiologues exerçant en secteur 2.', NULL, true, 40, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-montants-des-depassements-d-honoraires-appl-2', 15, 'Quels sont les montants des dépassements d''honoraires applicables ?', 'Les dépassements d''honoraires sont les suivants : 40 € pour les infiltrations et ponctions sous échographie, 50 € pour les infiltrations et ponctions sous radiographie, 50 € pour les biopsies. Pour les radiologues exerçant en secteur 2 : 30 € pour les échographies et 30 € pour les mammographies.', NULL, true, 41, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ModuleInfoItem" ("id", "userProductId", "question", "reponse", "categorie", "enabled", "order", "createdAt", "updatedAt") VALUES ('quels-sont-les-moyens-pour-deposer-une-reclamation-3', 15, 'Quels sont les moyens pour déposer une réclamation ?', 'Mail, courrier, téléphone.', NULL, true, 42, NOW(), NOW()) ON CONFLICT ("id") DO NOTHING;
